-- Membership is mutated exclusively by controlled RPCs.
-- The invitation token is generated by the server, and only its SHA-256 hash is stored.
-- No user can directly insert into membership tables.
create or replace function public.create_my_couple()
returns uuid language plpgsql security definer set search_path = ''
as $$
declare v_user uuid := auth.uid(); v_id uuid;
begin
 if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if exists(select 1 from public.couple_members where user_id=v_user) then
   raise exception 'You already belong to a couple' using errcode='23505';
 end if;
 insert into public.couples(created_by) values(v_user) returning id into v_id;
 insert into public.couple_members(couple_id,user_id) values(v_id,v_user);
 return v_id;
end;
$$;
revoke all on function public.create_my_couple() from public;
grant execute on function public.create_my_couple() to authenticated;

create or replace function public.issue_couple_invite(p_token_hash text)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare v_user uuid := auth.uid(); v_couple uuid; v_id uuid;
begin
 if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid token hash'; end if;
 select couple_id into v_couple from public.couple_members where user_id=v_user;
 if v_couple is null then raise exception 'No couple found' using errcode='42501'; end if;
 perform 1 from public.couples where id=v_couple for update;
 if (select count(*) from public.couple_members where couple_id=v_couple)>=2 then
   raise exception 'Couple already has two members';
 end if;
 update public.couple_invites set revoked_at=now()
 where couple_id=v_couple and accepted_at is null and revoked_at is null;
 insert into public.couple_invites(couple_id,created_by,token_hash,expires_at)
 values(v_couple,v_user,p_token_hash,now()+interval '48 hours') returning id into v_id;
 return v_id;
end;
$$;
revoke all on function public.issue_couple_invite(text) from public;
grant execute on function public.issue_couple_invite(text) to authenticated;

-- This RPC intentionally does not share any historical records.
-- Consent is captured separately from membership; historical sharing
-- will be implemented after authorization and storage rules are audited.
alter table public.couple_members
 add column if not exists share_previous boolean not null default false;

create or replace function public.accept_couple_invite(p_token_hash text, p_share_previous boolean)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare v_user uuid := auth.uid(); v_couple uuid; v_invite uuid;
begin
 if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid invitation'; end if;
 if exists(select 1 from public.couple_members where user_id=v_user) then
   raise exception 'You already belong to a couple';
 end if;
 select id,couple_id into v_invite,v_couple from public.couple_invites
 where token_hash=p_token_hash and accepted_at is null
   and revoked_at is null and expires_at>now();
 if v_invite is null then raise exception 'Invitation expired or invalid'; end if;
 perform 1 from public.couples where id=v_couple for update;
 -- Lock and recheck to prevent concurrent acceptances.
 if not exists(select 1 from public.couple_invites
   where id=v_invite and accepted_at is null and revoked_at is null and expires_at>now())
 then raise exception 'Invitation already used'; end if;
 if (select count(*) from public.couple_members where couple_id=v_couple)>=2 then
   raise exception 'Couple already has two members';
 end if;
 insert into public.couple_members(couple_id,user_id,share_previous)
 values(v_couple,v_user,coalesce(p_share_previous,false));
 update public.couple_invites set accepted_by=v_user,accepted_at=now() where id=v_invite;
 return v_couple;
end;
$$;
revoke all on function public.accept_couple_invite(text,boolean) from public;
grant execute on function public.accept_couple_invite(text,boolean) to authenticated;

-- Allow each member to see their own membership without recursion.
create policy couple_members_read_self on public.couple_members
for select to authenticated using(user_id=auth.uid());
create policy couples_read_created on public.couples
for select to authenticated using(created_by=auth.uid());
